+  void _dispatchFrameTail(Map decoded) {
+    switch (decoded['type']) {
+      case 'network.drain':
+        _onNetworkDrainFrame(decoded['payload']);
+      case 'wakeup.dispatched':
+        _onWakeupFrame(decoded['payload']);
+      case 'pong':
+        break; // heartbeat ack
+      case 'error':
+        _onErrorFrame(decoded);
+      default:
+        break; // forward-compatible: ignore unknown frame types
